import numpy as np

def obs(agent=None, wall=True, prev=None, reward=None):
    x = np.zeros(500)
    if wall:
        for r in range(10):
            for c in range(10):
                if r in (0, 9) or c in (0, 9):
                    x[(r * 10 + c) * 5 + 3] = 1.0
    if agent is not None:
        r, c = agent; x[(r * 10 + c) * 5 + 0] = 1.0
    if prev is not None:
        r, c = prev; x[(r * 10 + c) * 5 + 4] = 1.0
    if reward is not None:
        r, c = reward; x[(r * 10 + c) * 5 + 2] = 1.0
    return x

actions = ['noop', 'up', 'down', 'left', 'right']

def run(batch):
    lg = forward(np.array(batch))
    e = np.exp(lg - lg.max(axis=1, keepdims=True))
    return e / e.sum(axis=1, keepdims=True)

