import numpy as np

def make_obs(agent=None, rewards=()):
    x = np.zeros(500, dtype=np.float32)
    def setc(r, c, ch):
        x[(r*10+c)*5 + ch] = 1.0
    for r in range(10):
        for c in range(10):
            if r in (0, 9) or c in (0, 9):
                setc(r, c, 3)          # wall border always present
    if agent:
        setc(agent[0], agent[1], 0)
    for (r, c) in rewards:
        setc(r, c, 2)
    return x

dir_idx = {'up': 1, 'down': 2, 'left': 3, 'right': 4}
