positions = [(2, 2), (2, 5), (2, 7), (4, 4), (5, 5), (6, 6), (7, 2), (7, 7)]

# baseline logits (agent only, wall border on)
base_out = forward(np.array([make_obs(agent=p) for p in positions]))
base = {p: base_out[i] for i, p in enumerate(positions)}

# reward-adjacent configs
