for p in positions:
    ar, ac = p
    for dname in ['up', 'down', 'left', 'right']:
        dr, dc = step[dname]
        rr, cc = ar + dr, ac + dc
        if 1 <= rr <= 8 and 1 <= cc <= 8:
            configs.append(make_obs(agent=p, rewards=[(rr, cc)]))
            meta.append((p, dname))

out = forward(np.array(configs))

# delta = logit(action toward reward) with reward  -  baseline logit(same action)
delta = {}
for (p, dname), lg in zip(meta, out):
    d = float(lg[dir_idx[dname]] - base[p][dir_idx[dname]])
    delta.setdefault(p, {})[dname] = round(d, 2)

for p in positions:
    if p in delta:
        gs = delta[p]
        print(f"{p}: " + "  ".join(f"{d}:{gs[d]:+.2f}" for d in ['up', 'down', 'left', 'right'] if d in gs))

