def make_obs(agent=None, prev=None, reward=None, mover=None):
    x = np.zeros(500)
    # wall border
    for r in range(10):
        for c in range(10):
            if r == 0 or r == 9 or c == 0 or c == 9:
                x[(r*10+c)*5 + 3] = 1.0
    if agent is not None:
        r, c = agent
        x[(r*10+c)*5 + 0] = 1.0
    if prev is not None:
        r, c = prev
        x[(r*10+c)*5 + 4] = 1.0
    if reward is not None:
        r, c = reward
        x[(r*10+c)*5 + 2] = 1.0
    if mover is not None:
        r, c = mover
        x[(r*10+c)*5 + 1] = 1.0
    return x

